INSERT INTO public.products (product_id, name, brand, category, description, attributes) VALUES ('apple-iphone-16', 'iPhone 16', 'Apple', 'phone', 'Mua iPhone 16 với giá giảm từ 900.000đ - 27.100.000đ khi bạn trao đổi iPhone SE (2nd generation) trở lên. Có hỗ trợ tài chính với lãi suất 0%. Mua ngay để được vận chuyển miễn phí.', '{"source_url": "https://www.apple.com/vn/shop/buy-iphone/iphone-16", "family": "iphone16", "screen": "Màn hình 6.1 inch Đi kèm dung lượng lưu trữ 128GB", "specs": {"Màu": "Đen, Trắng, Hồng, Xanh Mòng Két, Xanh Lưu Ly Thiết kế nhôm Mặt trước Ceramic Shield Mặt sau bằng kính pha màu (Đen, Hồng, Xanh Mòng Két, Xanh Lưu Ly)", "Dung Lượng Lưu Trữ": "128GB", "Kích Thước Và Trọng Lượng": "Rộng: 71,6 mm Cao: 147,6 mm Dày: 7,80 mm Trọng Lượng: 170 gram", "Màn Hình": "Màn hình Super Retina XDR Màn hình toàn phần OLED 6,1 inch (theo đường chéo) Độ phân giải 2556x1179 pixel với mật độ điểm ảnh 460 ppi Dynamic Island Màn hình HDR True Tone Dải màu rộng (P3) Haptic Touch Tỷ lệ tương phản 2.000.000:1 (tiêu chuẩn) Độ sáng tối đa 1000 nit (tiêu chuẩn); độ sáng đỉnh 1600 nit (HDR); độ sáng đỉnh 2000 nit (ngoài trời); độ sáng tối thiểu 1 nit Lớp phủ kháng dầu chống in dấu vân tay Hỗ trợ hiển thị đồng thời nhiều ngôn ngữ và ký tự Màn hình iPhone 16 có các góc bo tròn theo đường cong tuyệt đẹp và nằm gọn theo một hình chữ nhật chuẩn. Khi tính theo hình chữ nhật chuẩn,", "Chống Tia Nước, Chống Nước, Và Chống Bụi": "Đạt mức IP68 (chống nước ở độ sâu tối đa 6 mét trong vòng tối đa 30 phút) theo tiêu chuẩn IEC 60529", "Chip": "Chip A18 CPU 6 lõi với 2 lõi hiệu năng và 4 lõi tiết kiệm điện GPU 5 lõi Neural Engine 16 lõi", "Apple Intelligence và Siri AI": "Apple Intelligence thế hệ mới đặt bạn ở trọng tâm, được tích hợp trong nhiều ứng dụng và có thiết kế bảo vệ quyền riêng tư. Apple Intelligence là nguồn sức mạnh của Siri AI, phiên bản Siri hoàn toàn mới, cá nhân hơn, giao tiếp tốt hơn và mạnh mẽ hơn, cùng nhiều tính năng hữu ích trên các ứng dụng. Tìm hiểu thêm về Apple Intelligence", "Camera": "Hệ thống camera kép tiên tiến 48MP Fusion Main: 26 mm, khẩu độ ƒ/1,6, chống rung quang học dịch chuyển cảm biến, Focus Pixels 100%, hỗ trợ ảnh có độ phân giải siêu cao (24MP và 48MP) Đồng thời hỗ trợ Telephoto 2x 12MP: 52 mm, khẩu độ ƒ/1,6, chống rung quang học dịch chuyển cảm biến, Focus Pixels 100% 12MP Ultra Wide: 13 mm, khẩu độ ƒ/2,2 và trường ảnh 120°, Focus Pixels 100% Độ phóng đại quang học 2x, độ thu nhỏ quang học 2x; phạm vi thu phóng quang học 4x Độ thu phóng kỹ thuật số lên đến 10x Điều Khiển Camera Lớp bảo vệ ống kính bằng sapphire Flash True Tone Photonic Engine Deep Fusion HDR th", "Quay Video": "Quay video 4K Dolby Vision ở tốc độ 24 fps, 25 fps, 30 fps, hoặc 60 fps Quay video 1080p Dolby Vision ở tốc độ 25 fps, 30 fps, hoặc 60 fps Quay video 720p Dolby Vision ở tốc độ 30 fps Chế độ Điện Ảnh lên đến 4K Dolby Vision ở tốc độ 30 fps Chế độ Hành Động lên đến 2,8K Dolby Vision ở tốc độ 60 fps Quay video macro, bao gồm chế độ quay chậm và tua nhanh Hỗ trợ quay video chậm 1080p ở tốc độ 120 fps hoặc 240 fps Quay video không gian 1080p ở tốc độ 30 fps Video tua nhanh có chống rung Tua nhanh ở chế độ Ban Đêm Quay video QuickTake lên đến 4K Dolby Vision ở tốc độ 60 fps Chống rung quang học dịc", "Camera TrueDepth": "Camera 12MP Khẩu độ ƒ/1,9 Tự động lấy nét theo pha Focus Pixels Flash Retina Photonic Engine Deep Fusion HDR thông minh thế hệ 5 Ảnh chân dung thế hệ mới với tính năng Lấy Nét và Điều Khiển Chiều Sâu Hiệu ứng Chiếu Sáng Chân Dung với sáu chế độ Animoji và Memoji Chế độ Ban Đêm Phong Cách Nhiếp Ảnh 2 Chụp hình dải màu rộng cho ảnh và ảnh động Live Photos Hiệu chỉnh ống kính Tự động chống rung hình ảnh Chế độ Chụp Liên Tục Quay video 4K Dolby Vision ở tốc độ 24 fps, 25 fps, 30 fps, hoặc 60 fps Quay video 1080p Dolby Vision ở tốc độ 25 fps, 30 fps, hoặc 60 fps Chế độ Điện Ảnh hỗ trợ độ phân giải ", "Pin Và Nguồn Điện": "Thời gian xem video Lên đến 22 giờ Thời gian xem video (trực tuyến) Lên đến 18 giờ Thời gian nghe nhạc Lên đến 80 giờ Tích hợp pin sạc lithium-ion Khả năng sạc nhanh: Sạc lên đến 50% trong khoảng 30 phút với bộ tiếp hợp 20W trở lên (được bán riêng) sử dụng cáp sạc USB‑C, hoặc với bộ tiếp hợp 30W trở lên sử dụng Bộ Sạc MagSafe (cả hai đều được bán riêng)", "Face ID": "Camera TrueDepth hỗ trợ nhận diện khuôn mặt", "Yên Tâm": "SOS Khẩn Cấp Phát Hiện Va Chạm", "Mạng Di Động Và Không Dây": "Phiên bản A3287 * FDD‑5G NR (Băng tần n1, n2, n3, n5, n7, n8, n12, n20, n25, n26, n28, n30, n66, n70, n75, n76) TDD‑5G NR (Băng tần n38, n40, n41, n48, n53, n77, n78, n79) FDD‑LTE (Băng tần 1, 2, 3, 4, 5, 7, 8, 12, 13, 17, 18, 19, 20, 25, 26, 28, 30, 32, 66) TDD‑LTE (Băng tần 34, 38, 39, 40, 41, 42, 48, 53) UMTS/HSPA+/DC‑HSDPA (850, 900, 1700/2100, 1900, 2100 MHz) GSM/EDGE (850, 900, 1800, 1900 MHz) 5G (sub‑6 GHz) với 4x4 MIMO LTE Gigabit với 4x4 MIMO Wi‑Fi 7 (802.11be) với 2x2 MIMO Bluetooth 5.3 Chip Apple Ultra Wideband thế hệ thứ 2 Công nghệ mạng Thread NFC có chế độ đọc Thẻ Truy Cập Nhanh ", "Định Vị": "GPS, GLONASS, Galileo, QZSS và BeiDou La bàn kỹ thuật số Wi‑Fi Mạng di động Định vị vi mô iBeacon", "Các Nút Bấm Và Cổng Kết Nối Bên Ngoài": "Tăng/giảm âm lượng Nút Tác Vụ Điều Khiển Camera Nút sườn Loa stereo tích hợp sẵn Micrô tích hợp sẵn Cổng kết nối USB‑C Micrô tích hợp sẵn Loa stereo tích hợp sẵn", "Sạc Và Kết Nối": "Cổng kết nối USB‑C hỗ trợ: Sạc DisplayPort USB 2 (lên đến 480Mb/s)", "MagSafe Và Sạc Không Dây": "Sạc không dây MagSafe lên đến 25W Sạc không dây Qi2 lên đến 25W Dãy nam châm Nam châm căn chỉnh NFC Nhận Dạng Phụ Kiện Từ kế", "Cảm Biến": "Face ID Áp kế Con quay hồi chuyển độ lệch tương phản cao Gia tốc kế lực G cao Cảm biến tiệm cận Hai cảm biến ánh sáng môi trường xung quanh", "Thẻ SIM": "SIM kép (nano-SIM và eSIM) Hỗ trợ eSIM kép Tìm hiểu thêm về eSIM Tìm hiểu thêm về du lịch với eSIM", "Apple Pay": "Thanh toán qua iPhone bên trong các ứng dụng và trên các trang web bằng cách sử dụng Face ID Hoàn tất thanh toán với Apple Pay trên Mac của bạn Tìm hiểu thêm về Apple Pay", "Gọi Video": "Gọi video FaceTime qua mạng di động hoặc Wi‑Fi Gọi video FaceTime HD (1080p) qua mạng 5G hoặc Wi‑Fi SharePlay Chia sẻ màn hình Chế độ Chân Dung trong video FaceTime Âm Thanh Không Gian Chế độ micrô Tách Lời Nói và Âm Phổ Rộng Phóng to thu nhỏ với camera sau", "Gọi Thoại": "FaceTime âm thanh Gọi Wi‑Fi SharePlay Chia sẻ màn hình Âm Thanh Không Gian Chế độ micrô Tách Lời Nói và Âm Phổ Rộng", "Nghe Nhạc": "Các định dạng được hỗ trợ bao gồm AAC, APAC, MP3, Apple Lossless, FLAC, Dolby Digital, Dolby Digital Plus, và Dolby Atmos Chế độ Âm Thanh Không Gian Giới hạn âm lượng tối đa do người dùng quyết định", "Xem Video": "Các định dạng được hỗ trợ bao gồm HEVC, H.264, và AV1 HDR với công nghệ Dolby Vision, HDR10+/HDR10, và HLG AirPlay có thể phản chiếu màn hình, ảnh và video có độ phân giải lên đến 4K HDR lên Apple TV (thế hệ thứ 2 trở lên) hoặc TV thông minh có hỗ trợ AirPlay Hỗ trợ phản chiếu video và đầu ra video: Lên đến 4K HDR thông qua đầu ra DisplayPort nguyên bản bằng USB‑C hoặc Bộ Chuyển Đổi AV Kỹ Thuật Số USB‑C (phiên bản A2119; bộ chuyển đổi được bán riêng)", "Siri": "Nhận trợ giúp thực hiện các công việc hàng ngày như gửi tin nhắn, đặt lời nhắc và hơn thế nữa Kích hoạt chế độ rảnh tay chỉ bằng giọng nói với “Hey Siri” hoặc sử dụng Nhập Liệu Vào Siri Quyền riêng tư được bảo vệ mạnh mẽ nhất so với mọi trợ lý thông minh khác Với sự hỗ trợ của Apple Intelligence, Siri tự nhiên hơn và hữu ích hơn Tìm hiểu thêm về Siri", "Hệ Điều Hành": "iOS iOS là hệ điều hành an toàn và đậm chất riêng nhất từng có của chúng tôi dành cho điện thoại di động, iOS được trang bị các tính năng mạnh mẽ và được thiết kế để bảo vệ quyền riêng tư của bạn.", "Quyền Riêng Tư": "iPhone được thiết kế hoàn toàn để bảo vệ thông tin cá nhân của bạn. Mỗi chiếc iPhone đều sở hữu tính năng xác thực bảo mật. Các ứng dụng cần có sự đồng ý của bạn để theo dõi hoạt động của bạn trên ứng dụng hay website của các công ty khác. Tin nhắn iMessages và các cuộc gọi video FaceTime của bạn được mã hóa đầu cuối. Và hơn thế nữa. Tìm hiểu thêm về các tính năng bảo mật", "Cấp Độ Tương Thích Trợ Thính": "Tương Thích Với Thiết Bị Trợ Thính", "Yêu Cầu Hệ Thống": "Tài Khoản Apple (bắt buộc đối với một số tính năng) Truy cập Internet Quá trình đồng bộ hóa với Mac hoặc PC cần phải có: macOS Catalina 10.15 trở lên sử dụng Finder macOS High Sierra 10.13 cho tới macOS Mojave 10.14.6 sử dụng iTunes 12.8 trở lên Windows 10 trở lên sử dụng iTunes 12.12.10 trở lên (tải xuống miễn phí từ apple.com/vn/itunes/download )", "Môi Trường Hoạt Động": "Nhiệt độ môi trường khi hoạt động: 0° đến 35° C Nhiệt độ khi không hoạt động: −20° đến 45° C Độ ẩm tương đối: 5% đến 95% không ngưng tụ Độ cao hoạt động: được thử nghiệm ở độ cao lên đến 3.000 mét", "Trong Hộp Sản Phẩm": "iPhone sử dụng iOS Cáp Sạc USB‑C (1m) Tài liệu iPhone Và Môi Trường iPhone 16 được thiết kế nhằm giảm tác động đến môi trường: Xem Báo Cáo Môi Trường Về Sản Phẩm iPhone 16 (PDF) Tiến độ hướng tới mục tiêu Apple 2030 Hơn 30% hàm lượng vật liệu tái chế Giảm 30% lượng khí thải so với kịch bản kinh doanh thông thường theo mô hình của Apple Xem cam kết của Apple Materials 100% nhôm trong cấu trúc tản nhiệt bên dưới là nhôm tái chế 100% cô-ban trong pin là cô-ban tái chế Hơn 95% lithium trong pin là lithium tái chế — thành tựu đầu tiên từ Apple 100% vàng trong dây của tất cả camera và Điều Khiển Cam"}, "magsafe": true, "port": "USB-C"}');
INSERT INTO public.products (product_id, name, brand, category, description, attributes) VALUES ('apple-iphone-17', 'iPhone 17', 'Apple', 'phone', 'iPhone 17. Camera trước Center Stage. Ceramic Shield thế hệ mới nhất. Màn hình 6,3 inch ProMotion. Chip A19. Năm màu tuyệt đẹp.', '{"source_url": "https://www.apple.com/vn/shop/buy-iphone/iphone-17", "family": "iphone17", "specs": {"Màu": "Đen, Trắng, Xanh Lam Khói, Xanh Lá Xô Thơm, Tím Oải Hương Thiết kế nhôm Mặt trước Ceramic Shield 2 Mặt sau bằng kính pha màu (Đen, Xanh Lam Khói, Xanh Lá Xô Thơm, Tím Oải Hương)", "Dung Lượng Lưu Trữ": "256GB 512GB", "Kích Thước Và Trọng Lượng": "Rộng: 71,5 mm Cao: 149,6 mm Dày: 7,95 mm Trọng Lượng: 177 gram", "Màn Hình": "Màn hình Super Retina XDR Màn hình toàn phần OLED 6,3 inch (theo đường chéo) Độ phân giải 2622x1206 pixel với mật độ điểm ảnh 460 ppi Dynamic Island Màn hình Luôn Bật Công nghệ ProMotion với tốc độ làm mới thích ứng lên đến 120Hz Màn hình HDR True Tone Dải màu rộng (P3) Haptic Touch Tỷ lệ tương phản 2.000.000:1 (tiêu chuẩn) Độ sáng tối đa 1000 nit (tiêu chuẩn); độ sáng đỉnh 1600 nit (HDR); độ sáng đỉnh 3000 nit (ngoài trời); độ sáng tối thiểu 1 nit Lớp phủ kháng dầu chống in dấu vân tay Lớp phủ chống phản chiếu Hỗ trợ hiển thị đồng thời nhiều ngôn ngữ và ký tự Màn hình iPhone 17 có các góc bo ", "Chống Tia Nước, Chống Nước, Và Chống Bụi": "Đạt mức IP68 (chống nước ở độ sâu tối đa 6 mét trong vòng tối đa 30 phút) theo tiêu chuẩn IEC 60529", "Apple Intelligence và Siri AI": "Apple Intelligence thế hệ mới đặt bạn ở trọng tâm, được tích hợp trong nhiều ứng dụng và có thiết kế bảo vệ quyền riêng tư. Apple Intelligence là nguồn sức mạnh của Siri AI, phiên bản Siri hoàn toàn mới, cá nhân hơn, giao tiếp tốt hơn và mạnh mẽ hơn, cùng nhiều tính năng hữu ích trên các ứng dụng. Tìm hiểu thêm", "Chip": "Chip A19 CPU 6 lõi với 2 lõi hiệu năng và 4 lõi tiết kiệm điện GPU 5 lõi với Neural Accelerators Neural Engine 16 lõi Công nghệ dò tia tốc độ cao bằng phần cứng", "Camera": "Hệ thống camera 48MP Dual Fusion 48MP Fusion Main: 26 mm, khẩu độ ƒ/1.6, chống rung quang học dịch chuyển cảm biến, Focus Pixels 100%, hỗ trợ ảnh có độ phân giải siêu cao (24MP và 48MP) Đồng thời hỗ trợ Telephoto 2x chất lượng quang học 12MP: 52mm, khẩu độ ƒ/1.6, chống rung quang học dịch chuyển cảm biến, Focus Pixels 100% 48MP Fusion Ultra Wide: 13 mm, khẩu độ ƒ/2.2 và trường ảnh 120°, Hybrid Focus Pixels, hỗ trợ ảnh có độ phân giải siêu cao (24MP và 48MP) Độ phóng đại quang học 2x, độ thu nhỏ quang học 2x; phạm vi thu phóng quang học 4x Độ thu phóng kỹ thuật số lên đến 10x Lớp bảo vệ ống kín", "Quay Video": "Quay video 4K Dolby Vision ở tốc độ 24 fps, 25 fps, 30 fps, hoặc 60 fps Quay video 1080p Dolby Vision ở tốc độ 25 fps, 30 fps, hoặc 60 fps Quay video 720p Dolby Vision ở tốc độ 30 fps Chế độ Điện Ảnh lên đến 4K Dolby Vision ở tốc độ 30 fps Chế độ Hành Động lên đến 2,8K Dolby Vision ở tốc độ 60 fps Quay video macro, bao gồm chế độ quay chậm và tua nhanh Hỗ trợ quay video chậm 1080p ở tốc độ 120 fps hoặc 240 fps Quay video không gian 1080p ở tốc độ 30 fps Ghi Hình Kép lên đến 4K Dolby Vision ở tốc độ 30 fps Video tua nhanh có chống rung Tua nhanh ở chế độ Ban Đêm Quay video QuickTake lên đến 4K ", "Camera Trước": "Camera 18MP Center Stage Khẩu độ ƒ/1.9 Tự động lấy nét theo pha Focus Pixels Flash Retina Chạm để thu phóng và xoay Center Stage cho ảnh Quay video cực ổn định Ghi Hình Kép Center Stage cho cuộc gọi video Photonic Engine Deep Fusion HDR thông minh thế hệ 5 Ảnh chân dung thế hệ mới với tính năng Lấy Nét và Điều Khiển Chiều Sâu Hiệu ứng Chiếu Sáng Chân Dung với sáu chế độ Animoji và Memoji Chế độ Ban Đêm Phong Cách Nhiếp Ảnh thế hệ mới nhất Chụp hình dải màu rộng cho ảnh và ảnh động Live Photos Hiệu chỉnh ống kính Tự động chống rung hình ảnh Chế độ Chụp Liên Tục Quay video 4K Dolby Vision ở tốc ", "Pin Và Nguồn Điện": "Thời gian xem video Lên đến 30 giờ Thời gian xem video (trực tuyến) Lên đến 27 giờ Tích hợp pin sạc lithium‑ion Khả năng sạc nhanh: Sạc lên đến 50% trong 20 phút với bộ tiếp hợp 40W trở lên (được bán riêng) sử dụng cáp sạc USB‑C Sạc lên đến 50% trong 30 phút với bộ tiếp hợp 30W trở lên sử dụng Bộ Sạc MagSafe (cả hai đều được bán riêng)", "Face ID": "Hỗ trợ bởi công nghệ TrueDepth trong camera trước Center Stage", "Yên Tâm": "SOS Khẩn Cấp Phát Hiện Va Chạm", "Mạng Di Động Và Không Dây": "Phiên bản A3520 ** FDD‑5G NR (Băng tần n1, n2, n3, n5, n7, n8, n12, n20, n25, n26, n28, n30, n66, n70, n75) TDD‑5G NR (Băng tần n38, n40, n41, n48, n53, n77, n78, n79) FDD‑LTE (Băng tần 1, 2, 3, 4, 5, 7, 8, 12, 13, 17, 18, 19, 20, 25, 26, 28, 30, 32, 66) TDD‑LTE (Băng tần 34, 38, 39, 40, 41, 42, 48, 53) UMTS/HSPA+/DC-HSDPA (850, 900, 1700/2100, 1900, 2100 MHz) GSM/EDGE (850, 900, 1800, 1900 MHz) 5G (sub‑6 GHz) với 4x4 MIMO LTE Gigabit với 4x4 MIMO Chip mạng không dây Apple N1 Wi‑Fi 7 (802.11be) với 2x2 MIMO Bluetooth 6 Công nghệ mạng Thread Chip Apple Ultra Wideband thế hệ thứ 2 NFC có chế độ ", "Định Vị": "GPS tần số kép chuẩn xác (GPS, GLONASS, Galileo, QZSS, BeiDou và NavIC) La bàn kỹ thuật số Wi‑Fi Mạng di động Định vị vi mô iBeacon", "Các Nút Bấm Và Cổng Kết Nối Bên Ngoài": "Tăng/giảm âm lượng Nút Tác Vụ Điều Khiển Camera Nút sườn Loa stereo tích hợp sẵn Micrô tích hợp sẵn Cổng kết nối USB‑C Micrô tích hợp sẵn Loa stereo tích hợp sẵn", "Sạc Và Kết Nối": "Cổng kết nối USB‑C hỗ trợ: Sạc DisplayPort USB 2 (lên đến 480Mb/s)", "MagSafe và Sạc Không Dây": "Sạc không dây MagSafe lên đến 25W Sạc không dây Qi2 lên đến 25W Dãy nam châm Nam châm căn chỉnh NFC Nhận Dạng Phụ Kiện Từ kế", "Cảm Biến": "Face ID Áp kế Con quay hồi chuyển độ lệch tương phản cao Gia tốc kế lực G cao Cảm biến tiệm cận Hai cảm biến ánh sáng môi trường", "Thẻ SIM": "SIM kép (nano SIM và eSIM) Hỗ trợ eSIM kép Tìm hiểu thêm về eSIM Tìm hiểu thêm về du lịch với eSIM", "Apple Pay": "Thanh toán qua iPhone bên trong các ứng dụng và trên các trang web bằng cách sử dụng Face ID Hoàn tất thanh toán với Apple Pay trên Mac của bạn Tìm hiểu thêm về Apple Pay", "Gọi Video": "Gọi video FaceTime qua mạng di động hoặc Wi‑Fi Gọi video FaceTime HD (1080p) qua mạng 5G hoặc Wi‑Fi Center Stage cho cuộc gọi video SharePlay Chia sẻ màn hình Chế độ Chân Dung trong video FaceTime Âm Thanh Không Gian Chế độ micrô Tách Lời Nói và Âm Phổ Rộng Phóng to thu nhỏ với camera sau", "Gọi Thoại": "FaceTime âm thanh Gọi Wi‑Fi SharePlay Chia sẻ màn hình Âm Thanh Không Gian Chế độ micrô Tách Lời Nói và Âm Phổ Rộng", "Nghe Nhạc": "Các định dạng được hỗ trợ bao gồm AAC, APAC, MP3, Apple Lossless, FLAC, Dolby Digital, Dolby Digital Plus, và Dolby Atmos Chế độ Âm Thanh Không Gian Giới hạn âm lượng tối đa do người dùng quyết định", "Xem Video": "Các định dạng được hỗ trợ bao gồm HEVC, H.264 và AV1 HDR với công nghệ Dolby Vision, HDR10+/HDR10, và HLG AirPlay có thể phản chiếu màn hình, ảnh và video có độ phân giải lên đến 4K HDR lên Apple TV (thế hệ thứ 2 trở lên) hoặc TV thông minh có hỗ trợ AirPlay Hỗ trợ phản chiếu video và đầu ra video: Lên đến 4K HDR thông qua đầu ra DisplayPort nguyên bản bằng USB‑C hoặc Bộ Chuyển Đổi AV Kỹ Thuật Số USB‑C (phiên bản A2119; bộ chuyển đổi được bán riêng)", "Siri": "Nhận trợ giúp thực hiện các công việc hàng ngày như gửi tin nhắn, đặt lời nhắc và hơn thế nữa Kích hoạt chế độ rảnh tay chỉ bằng giọng nói với “Hey Siri” hoặc sử dụng Nhập Liệu Vào Siri Quyền riêng tư được bảo vệ mạnh mẽ nhất so với mọi trợ lý thông minh khác Với sự hỗ trợ của Apple Intelligence, Siri tự nhiên hơn và hữu ích hơn Tìm hiểu thêm về Siri", "Hệ Điều Hành": "iOS Là hệ điều hành an toàn và đậm chất riêng nhất từng có của chúng tôi dành cho điện thoại di động, iOS được trang bị các tính năng mạnh mẽ và được thiết kế để bảo vệ quyền riêng tư của bạn.", "Quyền Riêng Tư": "iPhone được thiết kế hoàn toàn để bảo vệ thông tin cá nhân của bạn. Mỗi chiếc iPhone đều sở hữu tính năng xác thực bảo mật bằng gương mặt. Các ứng dụng cần có sự đồng ý của bạn để theo dõi hoạt động của bạn trên ứng dụng hay website của các công ty khác. Tin nhắn iMessages và các cuộc gọi video FaceTime của bạn được mã hóa đầu cuối. Và hơn thế nữa. Tìm hiểu thêm về các tính năng bảo mật", "Cấp Độ Tương Thích Trợ Thính": "Tương Thích Với Thiết Bị Trợ Thính", "Yêu Cầu Hệ Thống": "Tài Khoản Apple (bắt buộc đối với một số tính năng) Truy cập Internet Quá trình đồng bộ hóa với Mac hoặc PC cần phải có: macOS Catalina 10.15 trở lên sử dụng Finder macOS High Sierra 10.13 cho tới macOS Mojave 10.14.6 sử dụng iTunes 12.8 trở lên Windows 10 trở lên sử dụng iTunes 12.12.10 trở lên (tải xuống miễn phí từ apple.com/vn/itunes/download )", "Môi Trường Hoạt Động": "Nhiệt độ môi trường khi hoạt động: 0° đến 35° C Nhiệt độ khi không hoạt động: −20° đến 45° C Độ ẩm tương đối: 5% đến 95% không ngưng tụ Độ cao hoạt động: được thử nghiệm ở độ cao lên đến 3.000 mét", "Trong Hộp Sản Phẩm": "iPhone với iOS 27 Cáp Sạc USB‑C (1m) Tài liệu iPhone Và Môi Trường iPhone 17 được thiết kế để giảm tác động đến môi trường: Xem Báo Cáo Môi Trường Về Sản Phẩm iPhone 17 (PDF) Tiến độ hướng tới mục tiêu Apple 2030 Apple 2030 là cam kết của chúng tôi để đạt được trung hòa carbon cho toàn bộ dấu chân của mình. Kế hoạch của chúng tôi là loại bỏ carbon một cách nghiêm ngặt và tập trung vào chuyển đổi sang điện phát thải carbon thấp, được thiết kế bằng các vật liệu tái chế và phát thải carbon thấp, và ưu tiên những cách thức phát thải carbon thấp hơn khi vận chuyển sản phẩm, như vận tải đường biển. "}, "magsafe": true, "port": "USB-C"}');
INSERT INTO public.products (product_id, name, brand, category, description, attributes) VALUES ('apple-iphone-17e', 'iPhone 17e', 'Apple', 'phone', 'iPhone 17e. Ceramic Shield 2 bền chắc. Thời lượng pin dài. Camera 48MP. Dung lượng lưu trữ 256GB. Chip A19. iOS 26. Được thiết kế cho Apple Intelligence.', '{"source_url": "https://www.apple.com/vn/shop/buy-iphone/iphone-17e", "family": "iphone17e", "specs": {"Màu": "Đen, Trắng, Hồng Phai Thiết kế nhôm Mặt trước Ceramic Shield 2 Mặt sau bằng kính", "Dung Lượng Lưu Trữ": "256GB 512GB", "Kích Thước Và Trọng Lượng": "Rộng: 71,5 mm Cao: 146,7 mm Dày: 7,80 mm Trọng Lượng: 170 gram", "Màn Hình": "Màn hình Super Retina XDR Màn hình toàn phần OLED 6,1 inch (theo đường chéo) Độ phân giải 2532x1170 pixel với mật độ điểm ảnh 460 ppi Màn hình HDR True Tone Dải màu rộng (P3) Haptic Touch Tỷ lệ tương phản 2.000.000:1 (tiêu chuẩn) Độ sáng tối đa 800 nit (tiêu chuẩn); độ sáng đỉnh 1200 nit (HDR) Lớp phủ kháng dầu chống in dấu vân tay Lớp phủ chống phản chiếu Hỗ trợ hiển thị đồng thời nhiều ngôn ngữ và ký tự Màn hình iPhone 17e có các góc bo tròn theo đường cong tuyệt đẹp và nằm gọn theo một hình chữ nhật chuẩn. Khi tính theo hình chữ nhật chuẩn, kích thước màn hình theo đường chéo là 6,06 inch (", "Chống Tia Nước, Chống Nước và Chống Bụi": "Đạt mức IP68 (chống nước ở độ sâu tối đa 6 mét trong vòng tối đa 30 phút) theo tiêu chuẩn IEC 60529", "Apple Intelligence và Siri AI": "Apple Intelligence thế hệ mới đặt bạn ở trọng tâm, được tích hợp trong nhiều ứng dụng và có thiết kế bảo vệ quyền riêng tư. Apple Intelligence là nguồn sức mạnh của Siri AI, phiên bản Siri hoàn toàn mới, cá nhân hơn, giao tiếp tốt hơn và mạnh mẽ hơn, cùng nhiều tính năng hữu ích trên các ứng dụng. Tìm hiểu thêm", "Chip": "Chip A19 CPU 6 lõi với 2 lõi hiệu năng và 4 lõi tiết kiệm điện GPU 4 lõi với Neural Accelerators Neural Engine 16 lõi Công nghệ dò tia tốc độ cao bằng phần cứng", "Camera": "Hệ thống camera 48MP Fusion 48MP Fusion Main: 26 mm, khẩu độ ƒ/1.6, chống rung quang học, Hybrid Focus Pixels, ảnh có độ phân giải siêu cao (24MP và 48MP) Đồng thời hỗ trợ Telephoto 2x 12MP: 52 mm, khẩu độ ƒ/1.6, chống rung quang học, Hybrid Focus Pixels Độ thu phóng kỹ thuật số lên đến 10x Lớp bảo vệ ống kính bằng sapphire Flash True Tone Photonic Engine Deep Fusion HDR thông minh thế hệ 5 Ảnh chân dung thế hệ mới với tính năng Lấy Nét và Điều Khiển Chiều Sâu Hiệu ứng Chiếu Sáng Chân Dung với sáu chế độ Chế độ Ban Đêm Chụp ảnh toàn cảnh Panorama (lên đến 63MP) Phong Cách Nhiếp Ảnh Chụp hình d", "Quay Video": "Quay video 4K Dolby Vision ở tốc độ 24 fps, 25 fps, 30 fps, hoặc 60 fps Quay video 1080p Dolby Vision ở tốc độ 25 fps, 30 fps, hoặc 60 fps Quay video 720p Dolby Vision ở tốc độ 30 fps Hỗ trợ quay video chậm 1080p ở tốc độ 120 fps hoặc 240 fps Video tua nhanh có chống rung Tua nhanh ở chế độ Ban Đêm Quay video QuickTake Chống rung quang học cho video Độ thu phóng kỹ thuật số lên đến 6x Phóng đại âm thanh Flash True Tone Chống rung video kỹ thuật số (4K, 1080p, và 720p) Video tự động lấy nét liên tiếp Chụp ảnh tĩnh 8MP trong khi quay video 4K Thu phóng khi xem Định dạng của video được quay: HEVC", "Camera Trước": "Camera 12MP TrueDepth Khẩu độ ƒ/1.9 Tự động lấy nét theo pha Focus Pixels Flash Retina Photonic Engine Deep Fusion HDR thông minh thế hệ 5 Ảnh chân dung thế hệ mới với tính năng Lấy Nét và Điều Khiển Chiều Sâu Hiệu ứng Chiếu Sáng Chân Dung với sáu chế độ Animoji và Memoji Chế độ Ban Đêm Phong Cách Nhiếp Ảnh Chụp hình dải màu rộng cho ảnh và ảnh động Live Photos Hiệu chỉnh ống kính Tự động chống rung hình ảnh Chế độ Chụp Liên Tục Quay video 4K Dolby Vision ở tốc độ 24 fps, 25 fps, 30 fps, hoặc 60 fps Quay video 1080p Dolby Vision ở tốc độ 25 fps, 30 fps, hoặc 60 fps Hỗ trợ quay video chậm 1080p", "Pin Và Nguồn Điện": "Thời gian xem video: Lên đến 26 giờ Thời gian xem video (trực tuyến) Lên đến 21 giờ Khả năng sạc nhanh Sạc lên đến 50% trong 30 phút với bộ tiếp hợp 20W trở lên (được bán riêng) sử dụng cáp sạc USB‑C Tích hợp pin sạc lithium‑ion", "Face ID": "Camera TrueDepth hỗ trợ nhận diện khuôn mặt", "Yên Tâm": "SOS Khẩn Cấp Phát Hiện Va Chạm", "Định Vị": "GPS, GLONASS, Galileo, QZSS, BeiDou và NavIC La bàn kỹ thuật số Wi‑Fi Mạng di động Định vị vi mô iBeacon", "Các Nút Bấm Và Cổng Kết Nối Bên Ngoài": "Tăng/giảm âm lượng Nút Tác Vụ Nút sườn Loa stereo tích hợp sẵn Micrô tích hợp sẵn Cổng kết nối USB‑C Micrô tích hợp sẵn Loa stereo tích hợp sẵn", "Sạc Và Kết Nối": "Cổng kết nối USB‑C hỗ trợ: Sạc USB 2 (lên đến 480Mb/s)", "MagSafe và Sạc Không Dây": "Sạc không dây MagSafe lên đến 15W Sạc không dây Qi2 lên đến 15W Dãy nam châm Nam châm căn chỉnh NFC Nhận Dạng Phụ Kiện Từ kế", "Cảm Biến": "Face ID Áp kế Con quay hồi chuyển độ lệch tương phản cao Gia tốc kế lực G cao Cảm biến tiệm cận Hai cảm biến ánh sáng môi trường", "Thẻ SIM": "SIM kép (nano SIM và eSIM) Hỗ trợ eSIM kép Tìm hiểu thêm về eSIM Tìm hiểu thêm về du lịch với eSIM", "Apple Pay": "Thanh toán qua iPhone tại các cửa hàng, bên trong các ứng dụng và trên trang web bằng cách sử dụng Face ID Hoàn tất thanh toán với Apple Pay trên Mac của bạn Tìm hiểu thêm về Apple Pay", "Gọi Video": "Gọi video FaceTime qua mạng di động hoặc Wi‑Fi Gọi video FaceTime HD (1080p) qua mạng 5G hoặc Wi‑Fi SharePlay Chia sẻ màn hình Chế độ Chân Dung trong video FaceTime Âm Thanh Không Gian Chế độ micrô Tách Lời Nói và Âm Phổ Rộng Phóng to thu nhỏ với camera sau", "Gọi Thoại": "FaceTime âm thanh Gọi Wi‑Fi SharePlay Chia sẻ màn hình Âm Thanh Không Gian Chế độ micrô Tách Lời Nói và Âm Phổ Rộng", "Nghe Nhạc": "Các định dạng được hỗ trợ bao gồm AAC, MP3, Apple Lossless, FLAC, Dolby Digital, Dolby Digital Plus, và Dolby Atmos Chế độ Âm Thanh Không Gian Giới hạn âm lượng tối đa do người dùng quyết định", "Xem Video": "Các định dạng được hỗ trợ bao gồm HEVC, H.264 và AV1 Hỗ trợ Dolby Vision, HDR10+/HDR10, và HLG AirPlay có thể phản chiếu màn hình, ảnh và video có độ phân giải lên đến 4K HDR lên Apple TV (thế hệ thứ 2 trở lên) hoặc TV thông minh có hỗ trợ AirPlay", "Siri": "Nhận trợ giúp thực hiện các công việc hàng ngày như gửi tin nhắn, đặt lời nhắc và hơn thế nữa Kích hoạt chế độ rảnh tay chỉ bằng giọng nói với “Hey Siri” hoặc sử dụng Nhập Liệu Vào Siri Quyền riêng tư được bảo vệ mạnh mẽ nhất so với mọi trợ lý thông minh khác Với sự hỗ trợ của Apple Intelligence, Siri tự nhiên hơn và hữu ích hơn Tìm hiểu thêm về Siri", "Hệ Điều Hành": "iOS Là hệ điều hành an toàn và đậm chất riêng nhất từng có của chúng tôi dành cho điện thoại di động, iOS được trang bị các tính năng mạnh mẽ và được thiết kế để bảo vệ quyền riêng tư của bạn.", "Quyền Riêng Tư": "iPhone được thiết kế hoàn toàn để bảo vệ thông tin cá nhân của bạn. Mỗi chiếc iPhone đều sở hữu tính năng xác thực bảo mật bằng gương mặt. Các ứng dụng cần có sự đồng ý của bạn để theo dõi hoạt động của bạn trên ứng dụng hay website của các công ty khác. Tin nhắn iMessages và các cuộc gọi video FaceTime của bạn được mã hóa đầu cuối. Và hơn thế nữa. Tìm hiểu thêm về các tính năng bảo mật", "Cấp Độ Tương Thích Trợ Thính": "Tương Thích Với Thiết Bị Trợ Thính", "Yêu Cầu Hệ Thống": "Tài Khoản Apple (bắt buộc đối với một số tính năng) Truy cập Internet Quá trình đồng bộ hóa với Mac hoặc PC cần phải có: macOS Catalina 10.15 trở lên sử dụng Finder macOS High Sierra 10.13 cho tới macOS Mojave 10.14.6 sử dụng iTunes 12.8 trở lên Windows 10 trở lên sử dụng iTunes 12.12.10 trở lên (tải xuống miễn phí từ apple.com/vn/itunes/download )", "Môi Trường Hoạt Động": "Nhiệt độ môi trường khi hoạt động: 0° đến 35° C Nhiệt độ khi không hoạt động: −20° đến 45° C Độ ẩm tương đối: 5% đến 95% không ngưng tụ Độ cao hoạt động: được thử nghiệm ở độ cao lên đến 3.000 mét", "Trong Hộp Sản Phẩm": "iPhone với iOS 27 Cáp Sạc USB‑C (1 m) Tài liệu iPhone Và Môi Trường iPhone 17e được thiết kế để giảm tác động đến môi trường: Xem Báo Cáo Môi Trường Về Sản Phẩm iPhone 17e (PDF) Tiến độ hướng tới mục tiêu Apple 2030 Apple 2030 là cam kết của chúng tôi để đạt được trung hòa carbon cho toàn bộ dấu chân của mình. Kế hoạch của chúng tôi là loại bỏ carbon một cách nghiêm ngặt và tập trung vào chuyển đổi sang điện phát thải carbon thấp, được thiết kế bằng các vật liệu tái chế và phát thải carbon thấp, và ưu tiên những cách thức phát thải carbon thấp hơn khi vận chuyển sản phẩm, như vận tải đường biể"}, "magsafe": true, "port": "USB-C"}');
INSERT INTO public.products (product_id, name, brand, category, description, attributes) VALUES ('apple-iphone-18-pro-max', 'iPhone 18 Pro Max', 'Apple', 'phone', 'iPhone 18 Pro. Một cỗ máy AI siêu mạnh. Camera 48MP Main với khẩu độ thay đổi. Bước nhảy vọt về thời lượng pin. Buồng hơi thế hệ mới. Chip A20 Pro.', '{"source_url": "https://www.apple.com/vn/shop/buy-iphone/iphone-18-pro", "family": "iphone18promax", "screen": "Màn hình 6,9 inch", "specs": {"Chống Tia Nước, Chống Nước, Và Chống Bụi": "Đạt mức IP68 (chống nước ở độ sâu tối đa 6 mét trong vòng tối đa 30 phút) theo tiêu chuẩn IEC 60529", "Apple Intelligence và Siri AI": "Apple Intelligence thế hệ mới đặt bạn ở trọng tâm, được tích hợp trong nhiều ứng dụng và có thiết kế bảo vệ quyền riêng tư. Apple Intelligence là nguồn sức mạnh của Siri AI, phiên bản Siri hoàn toàn mới, cá nhân hơn, giao tiếp tốt hơn và mạnh mẽ hơn, cùng nhiều tính năng hữu ích trên các ứng dụng. Tìm hiểu thêm", "Chip": "Chip A20 Pro CPU 6 lõi với 2 lõi siêu xử lý và 4 lõi tiết kiệm điện GPU 7 lõi với Neural Accelerators Bộ Đôi Neural Engine 16 lõi Công nghệ dò tia tốc độ cao bằng phần cứng", "Camera": "Hệ thống camera 48MP Pro Fusion 48MP Fusion Main: với khẩu độ thay đổi (ƒ/1,48, ƒ/1,8, ƒ/2,8, ƒ/4,0): 24 mm, chống rung quang học dịch chuyển cảm biến thế hệ thứ hai, Focus Pixels 100%, hỗ trợ ảnh có độ phân giải siêu cao (24MP và 48MP) Đồng thời hỗ trợ Telephoto 2x chất lượng quang học 12MP: 48 mm, chống rung quang học dịch chuyển cảm biến thế hệ thứ hai, Focus Pixels 100% 48MP Fusion Ultra Wide: 13 mm, khẩu độ ƒ/2,2 và trường ảnh 120°, Hybrid Focus Pixels, hỗ trợ ảnh có độ phân giải siêu cao (24MP và 48MP) 48MP Fusion Telephoto: 100 mm (4x), khẩu độ ƒ/2,8, Hybrid Focus Pixels, chống rung qua", "Quay Video": "Quay video 4K Dolby Vision ở tốc độ 24 fps, 25 fps, 30 fps, 60 fps, 100 fps (Fusion Main), hoặc 120 fps (Fusion Main) Quay video 1080p Dolby Vision ở tốc độ 25 fps, 30 fps, 60 fps, hoặc 120 fps (Fusion Main) Quay video 720p Dolby Vision ở tốc độ 30 fps Chế độ Điện Ảnh lên đến 4K Dolby Vision ở tốc độ 60 fps Hiệu ứng chế độ Điện Ảnh từ video Các điều khiển Pro cho khẩu độ ống kính, tốc độ màn trập, cân bằng trắng và xem biểu đồ Theo dõi lấy nét thông minh Cải thiện quay video trong điều kiện ánh sáng yếu ở độ phân giải 1080p Chế độ Hành Động lên đến 2,8K Dolby Vision ở tốc độ 60 fps Quay video ", "Camera Trước": "Camera 18MP Center Stage Khẩu độ ƒ/1,9 Tự động lấy nét theo pha Focus Pixels Flash Retina Chạm để thu phóng và xoay Center Stage cho ảnh Quay video cực ổn định Ghi Hình Kép Center Stage cho cuộc gọi video Các điều khiển Pro cho tốc độ màn trập, cân bằng trắng và xem biểu đồ Photonic Engine Deep Fusion HDR thông minh thế hệ 5 Ảnh chân dung thế hệ mới với tính năng Lấy Nét và Điều Khiển Chiều Sâu Hiệu ứng Chiếu Sáng Chân Dung với sáu chế độ Animoji và Memoji Chế độ Ban Đêm Phong Cách Nhiếp Ảnh 3 Theo dõi lấy nét thông minh Cải thiện quay video trong điều kiện ánh sáng yếu ở độ phân giải 1080p Pr", "Face ID": "Hỗ trợ bởi công nghệ TrueDepth trong camera trước Center Stage", "Yên Tâm": "SOS Khẩn Cấp Phát Hiện Va Chạm", "Mạng Di Động Và Không Dây": "5G (sub-6 GHz) với 4x4 MIMO LTE Gigabit với 4x4 MIMO Chip mạng không dây Apple N1 Wi‑Fi 7 (802.11be) với 2x2 MIMO Bluetooth 6 Công nghệ mạng Thread Chip Apple Ultra Wideband thế hệ thứ 2 NFC có chế độ đọc Thẻ Truy Cập Nhanh với chế độ dự trữ năng lượng Modem di động Apple C2", "Định Vị": "GPS tần số kép chuẩn xác (GPS, GLONASS, Galileo, QZSS, BeiDou và NavIC) La bàn kỹ thuật số Wi-Fi Mạng di động Định vị vi mô iBeacon", "Các Nút Bấm Và Cổng Kết Nối Bên Ngoài": "Tăng/giảm âm lượng Nút Tác Vụ Điều Khiển Camera Nút sườn Loa stereo tích hợp sẵn Micrô tích hợp sẵn Cổng kết nối USB‑C Micrô tích hợp sẵn Loa stereo tích hợp sẵn", "Sạc Và Kết Nối": "Cổng kết nối USB‑C hỗ trợ: Sạc DisplayPort USB 3 (lên đến 10Gb/s)", "MagSafe và Sạc Không Dây": "Sạc không dây MagSafe lên đến 25W Sạc không dây Qi2 lên đến 25W Dãy nam châm Nam châm căn chỉnh NFC Nhận Dạng Phụ Kiện Từ kế", "Cảm Biến": "Face ID LiDAR Scanner Áp kế Con quay hồi chuyển độ lệch tương phản cao Gia tốc kế lực G cao Cảm biến tiệm cận Hai cảm biến ánh sáng môi trường", "Thẻ SIM": "SIM kép (nano SIM và eSIM) Hỗ trợ eSIM kép Tìm hiểu thêm về eSIM Tìm hiểu thêm về du lịch với eSIM", "Apple Pay": "Thanh toán qua iPhone tại các cửa hàng, bên trong các ứng dụng và trên các trang web bằng cách sử dụng Face ID Hoàn tất thanh toán với Apple Pay trên Mac của bạn Tìm hiểu thêm về Apple Pay", "Gọi Video": "Gọi video FaceTime qua mạng di động hoặc Wi‑Fi Gọi video FaceTime HD (1080p) qua mạng 5G hoặc Wi‑Fi Center Stage cho cuộc gọi video SharePlay Chia sẻ màn hình Chế độ Chân Dung trong video FaceTime Âm Thanh Không Gian Chế độ micrô Tách Lời Nói và Âm Phổ Rộng Thu phóng quang học với camera sau", "Gọi Thoại": "FaceTime âm thanh Gọi Wi‑Fi SharePlay Chia sẻ màn hình Âm Thanh Không Gian Chế độ micrô Tách Lời Nói và Âm Phổ Rộng", "Nghe Nhạc": "Các định dạng được hỗ trợ bao gồm AAC, APAC, MP3, Apple Lossless, FLAC, Dolby Digital, Dolby Digital Plus, và Dolby Atmos Chế độ Âm Thanh Không Gian Giới hạn âm lượng tối đa do người dùng quyết định", "Xem Video": "Các định dạng được hỗ trợ bao gồm HEVC, H.264, AV1, và ProRes HDR với công nghệ Dolby Vision, HDR10+/HDR10, và HLG AirPlay có thể phản chiếu màn hình, ảnh và video có độ phân giải lên đến 4K HDR lên Apple TV (thế hệ thứ 2 trở lên) hoặc TV thông minh có hỗ trợ AirPlay Hỗ trợ phản chiếu video và đầu ra video: Lên đến 4K HDR thông qua đầu ra DisplayPort nguyên bản bằng USB‑C hoặc Bộ Chuyển Đổi AV Kỹ Thuật Số USB‑C (phiên bản A2119; bộ chuyển đổi được bán riêng)", "Siri": "Nhận trợ giúp thực hiện các công việc hàng ngày như gửi tin nhắn, đặt lời nhắc và hơn thế nữa Kích hoạt chế độ rảnh tay chỉ bằng giọng nói với “Hey Siri” hoặc sử dụng Nhập Liệu Vào Siri Quyền riêng tư được bảo vệ mạnh mẽ nhất so với mọi trợ lý thông minh khác Với sự hỗ trợ của Apple Intelligence, Siri tự nhiên hơn và hữu ích hơn Tìm hiểu thêm về Siri", "Hệ Điều Hành": "iOS 27 Là hệ điều hành an toàn và đậm chất riêng nhất từng có của chúng tôi dành cho điện thoại di động, iOS 27 được trang bị các tính năng mạnh mẽ và được thiết kế để bảo vệ quyền riêng tư của bạn.", "Quyền Riêng Tư": "iPhone được thiết kế hoàn toàn để bảo vệ thông tin cá nhân của bạn. Mọi chiếc iPhone đều có tính năng xác thực bảo mật. Các ứng dụng cần có sự đồng ý của bạn để theo dõi hoạt động của bạn trên ứng dụng hay website của các công ty khác. Tin nhắn iMessages và các cuộc gọi video FaceTime của bạn được mã hóa đầu cuối. Và hơn thế nữa. Tìm hiểu thêm về các tính năng bảo mật", "Cấp Độ Tương Thích Trợ Thính": "Tương Thích Với Thiết Bị Trợ Thính", "Yêu Cầu Hệ Thống": "Tài Khoản Apple (bắt buộc đối với một số tính năng) Truy cập Internet Quá trình đồng bộ hóa với Mac hoặc PC cần phải có: macOS Catalina 10.15 trở lên sử dụng Finder macOS High Sierra 10.13 cho tới macOS Mojave 10.14.6 sử dụng iTunes 12.8 trở lên Windows 10 trở lên sử dụng iTunes 12.12.10 trở lên (tải xuống miễn phí từ apple.com/vn/itunes/download )", "Trong Hộp Sản Phẩm": "iPhone với iOS 27 Cáp Sạc USB‑C (1 m) Tài liệu iPhone Và Môi Trường Xem Báo Cáo Môi Trường Về Sản Phẩm iPhone 18 Pro và iPhone 18 Pro Max (PDF) , opens in new tab Tiến độ hướng tới mục tiêu Apple 2030 Apple 2030 là mục tiêu chúng tôi đề ra để đạt được trung hòa carbon trong toàn bộ chuỗi giá trị của mình. Chúng tôi thiết kế sản phẩm phát thải carbon ít hơn bằng cách ưu tiên sử dụng vật liệu tái chế và tái tạo, vật liệu phát thải carbon thấp, đồng thời tập trung vào hiệu quả tiết kiệm điện của phần mềm và phần cứng. Xem cam kết của Apple Vật Liệu iPhone 18 Pro và iPhone 18 Pro Max được làm từ 4", "Màu": "Đen, Bạc, Băng Thanh, Đỏ Burgundy Thiết kế nguyên khối nhôm Mặt trước Ceramic Shield 2 Mặt sau Ceramic Shield", "Dung Lượng Lưu Trữ": "256GB 512GB 1TB 2TB", "Kích Thước Và Trọng Lượng": "Rộng: 78,0 mm Cao: 163,4 mm Dày: 8,75 mm Trọng Lượng: 249 gram", "Màn Hình": "Màn hình Super Retina XDR Màn hình toàn phần OLED 6,9 inch (theo đường chéo) Độ phân giải 2868x1320 pixel với mật độ điểm ảnh 460 ppi Màn hình iPhone 18 Pro Max có các góc bo tròn theo đường cong tuyệt đẹp và nằm gọn theo một hình chữ nhật chuẩn. Khi tính theo hình chữ nhật chuẩn, kích thước màn hình theo đường chéo là 6,86 inch (diện tích hiển thị thực tế nhỏ hơn).", "Pin Và Nguồn Điện": "Sử dụng thông thường Lên đến 29 giờ Thời gian xem video Lên đến 43 giờ Thời gian xem video (trực tuyến) Lên đến 38 giờ"}, "magsafe": true, "port": "USB-C"}');
INSERT INTO public.products (product_id, name, brand, category, description, attributes) VALUES ('apple-iphone-18-pro', 'iPhone 18 Pro', 'Apple', 'phone', 'iPhone 18 Pro. Một cỗ máy AI siêu mạnh. Camera 48MP Main với khẩu độ thay đổi. Bước nhảy vọt về thời lượng pin. Buồng hơi thế hệ mới. Chip A20 Pro.', '{"source_url": "https://www.apple.com/vn/shop/buy-iphone/iphone-18-pro", "family": "iphone18pro", "screen": "Màn hình 6,3 inch", "specs": {"Chống Tia Nước, Chống Nước, Và Chống Bụi": "Đạt mức IP68 (chống nước ở độ sâu tối đa 6 mét trong vòng tối đa 30 phút) theo tiêu chuẩn IEC 60529", "Apple Intelligence và Siri AI": "Apple Intelligence thế hệ mới đặt bạn ở trọng tâm, được tích hợp trong nhiều ứng dụng và có thiết kế bảo vệ quyền riêng tư. Apple Intelligence là nguồn sức mạnh của Siri AI, phiên bản Siri hoàn toàn mới, cá nhân hơn, giao tiếp tốt hơn và mạnh mẽ hơn, cùng nhiều tính năng hữu ích trên các ứng dụng. Tìm hiểu thêm", "Chip": "Chip A20 Pro CPU 6 lõi với 2 lõi siêu xử lý và 4 lõi tiết kiệm điện GPU 7 lõi với Neural Accelerators Bộ Đôi Neural Engine 16 lõi Công nghệ dò tia tốc độ cao bằng phần cứng", "Camera": "Hệ thống camera 48MP Pro Fusion 48MP Fusion Main: với khẩu độ thay đổi (ƒ/1,48, ƒ/1,8, ƒ/2,8, ƒ/4,0): 24 mm, chống rung quang học dịch chuyển cảm biến thế hệ thứ hai, Focus Pixels 100%, hỗ trợ ảnh có độ phân giải siêu cao (24MP và 48MP) Đồng thời hỗ trợ Telephoto 2x chất lượng quang học 12MP: 48 mm, chống rung quang học dịch chuyển cảm biến thế hệ thứ hai, Focus Pixels 100% 48MP Fusion Ultra Wide: 13 mm, khẩu độ ƒ/2,2 và trường ảnh 120°, Hybrid Focus Pixels, hỗ trợ ảnh có độ phân giải siêu cao (24MP và 48MP) 48MP Fusion Telephoto: 100 mm (4x), khẩu độ ƒ/2,8, Hybrid Focus Pixels, chống rung qua", "Quay Video": "Quay video 4K Dolby Vision ở tốc độ 24 fps, 25 fps, 30 fps, 60 fps, 100 fps (Fusion Main), hoặc 120 fps (Fusion Main) Quay video 1080p Dolby Vision ở tốc độ 25 fps, 30 fps, 60 fps, hoặc 120 fps (Fusion Main) Quay video 720p Dolby Vision ở tốc độ