INSERT INTO public.products (product_id, name, brand, category, description, attributes) VALUES ('samsung-galaxy-z-flip8', 'Galaxy Z Flip8', 'Samsung', 'phone', 'Mua Samsung Galaxy Z Flip 8 mới ngay hôm nay. Trải nghiệm chiếc điện thoại gập nhỏ gọn, mỏng và nhẹ hơn, được tích hợp Galaxy AI. Tận hưởng ưu đãi thu cũ đổi mới và trả góp 0%. Mua ngay tại Samsung Việt Nam.', '{"source_url": "https://www.samsung.com/vn/smartphones/galaxy-z-flip8/buy/", "model_name": "SM-F776B", "ram_by_storage": {"256GB": "12GB", "512GB": "12GB"}, "port": "USB-C", "estimated_price_skus": ["SM-F776BLIAXXV", "SM-F776BZKAXXV", "SM-F776BZWAXXV"]}');
INSERT INTO public.products (product_id, name, brand, category, description, attributes) VALUES ('samsung-galaxy-z-fold8-ultra', 'Galaxy Z Fold8 Ultra', 'Samsung', 'phone', 'Mua Samsung Galaxy Z Fold 8 Ultra mới ngay hôm nay. Trải nghiệm siêu phẩm điện thoại gập Samsung Galaxy với Galaxy AI, độ bền vượt trội, ưu đãi thu cũ đổi mới và chương trình trả góp 0%. Mua ngay tại Samsung Việt Nam.', '{"source_url": "https://www.samsung.com/vn/smartphones/galaxy-z-fold8-ultra/buy/", "model_name": "SM-F976B", "ram_by_storage": {"256GB": "12GB", "512GB": "12GB", "1TB": "16GB"}, "port": "USB-C"}');
INSERT INTO public.products (product_id, name, brand, category, description, attributes) VALUES ('samsung-galaxy-z-fold8', 'Galaxy Z Fold8', 'Samsung', 'phone', 'Mua Samsung Galaxy Z Fold 8 ngay hôm nay để tận hưởng trải nghiệm giải trí di động sống động trên màn hình rộng nhất từ trước đến nay. Nhận ưu đãi thu cũ đổi mới và chương trình trả góp 0% lãi suất. Mua ngay tại Samsung Việt Nam.', '{"source_url": "https://www.samsung.com/vn/smartphones/galaxy-z-fold8/buy/", "model_name": "SM-F971B", "ram_by_storage": {"256GB": "12GB", "512GB": "12GB", "1TB": "16GB"}, "port": "USB-C", "estimated_price_skus": ["SM-F971BZGDXXV", "SM-F971BZGGXXV"]}');
